/// The Rust Container.
struct EeWonContainer;

/// The window's fonts.
struct EeWonFontMap;

/// The clip stack (`mClipStack`).
struct EeWonGfx;

/// The Rust ListArea.
struct EeWonList;

/// The Rust PlatGUIFont.
struct EeWonPlatFont;

/// The window's own state.
struct EeWonPlatWin;

/// The Rust PlatWindowManager.
struct EeWonPlatWm;

/// The Rust RootContainer.
struct EeWonRoot;

/// The Rust surface.
struct EeWonSurface;

/// The Rust Window.
struct EeWonWindow;

/// The Rust WindowManager.
///
/// Every method runs on the GUI thread but PostEvent and PeekNextEvent, which other threads call (the original
/// locked `mDataCrit` there): they touch only `events` (a `Mutex`, never held across a call out) and
/// `cur_depth` (an atomic: the message loop's depth PostEvent reads), and make the event's `Hold` and the
/// `Signal` ops, which the C++ answers on any thread.
struct EeWonWm;

/// The host: `(component, op, a, b, c, d) -> result`. `component` is the C++ object the Rust one belongs to.
using EeWonGuiHostFn = ptrdiff_t(*)(void *component,
                                    EeWonGuiOp op,
                                    ptrdiff_t a,
                                    ptrdiff_t b,
                                    ptrdiff_t c,
                                    ptrdiff_t d);

/// A `WONRectangle` (x, y, width, height).
struct EeWonRect {
  int32_t x;
  int32_t y;
  int32_t width;
  int32_t height;
};

/// The platform's cursor calls (platform/PlatWindow.h), as the C++ shell hands them: PlatCursorSetSystem,
/// PlatCursorCreate, PlatCursorSet, PlatCursorDestroy.
struct EeWonPlatCursorFns {
  void (*set_system)(uint32_t cursor);
  void *(*create)(const uint32_t *bgra, int32_t width, int32_t height, int32_t hot_x, int32_t hot_y);
  void (*set)(void *cursor);
  void (*destroy)(void *cursor);
};

/// The host: the hook on the C++ Graphics `g` with up to seven ints at `args` and an object `p`; its answer.
using EeWonGfxHost = uint32_t(*)(void *g, EeWonGfxHook hook, const int32_t *args, const void *p);

/// The C++ Graphics' translation, colour and clip rectangle (`mTransX`, `mTransY`, `mColor`, `mClipRect`, in that
/// order).
struct EeWonGfxState {
  int32_t trans_x;
  int32_t trans_y;
  uint32_t color;
  EeWonRect clip;
};

/// Where a Graphics draws (PlatGraphics' members): the surface of the display context it is attached to (borrowed:
/// the image that owns the context keeps it; null while detached or when the context has none) and the context's
/// pixel scale.
struct EeWonGfxPlat {
  EeWonSurface *surface;
  float scale;
};

/// The game's Graphics (the C++ `Graphics` is this record since R6 WON GUI round 39, made, attached and freed here:
/// [`new_graphics`], [`free_graphics`]): the translation, colour and clip, the clip stack, the borrowed colour
/// scheme, the surface, and the display context and font (each held, as the original's SmartPtr members held them).
struct EeWonGraphics {
  EeWonGfxState st;
  /// the clip stack (owned)
  EeWonGfx *gfx;
  /// the `ColorScheme*` (borrowed; NULL: none)
  const void *scheme;
  EeWonGfxPlat plat;
  /// the `DisplayContext*` (held; 0: none)
  ptrdiff_t context;
  /// the `Font*` (held; 0: none)
  ptrdiff_t font;
};

/// One draw operation (`kind` and up to eight arguments; their meaning is the kind's).
struct EeWonDrawOp {
  int32_t kind;
  int32_t a;
  int32_t b;
  int32_t c;
  int32_t d;
  int32_t e;
  int32_t f;
  int32_t g;
  int32_t h;
};

/// One paint's inputs: the kind, the state bits (`EE_WON_MSPAINT_*`), the size and the kind's arguments.
struct EeWonMsPaint {
  EeWonMsPaintKind kind;
  uint32_t flags;
  int32_t width;
  int32_t height;
  int32_t a;
  int32_t b;
  int32_t c;
  int32_t d;
  int32_t e;
};

/// A rectangle (x, y, width, height).
struct EeWonRect4 {
  int32_t x;
  int32_t y;
  int32_t w;
  int32_t h;
};

/// A grabber's drawing state (`RootGrabberRead`): whether it needs drawing (`NeedDrawBG`), its image order (as the
/// map's `int` key), its image's place, its clip rectangle and its image.
struct EeWonRootGrab {
  int32_t need;
  int32_t order;
  int32_t x;
  int32_t y;
  EeWonRect4 clip;
  ptrdiff_t image;
};

/// One line break of a wrapped text (`WrappedText::BreakInfo`).
struct EeWonLineBreak {
  uint16_t break_pos;
  uint16_t next_start;
  uint16_t width;
};

/// Text measures the C++ answers (the original's font calls at the points the plan reaches them):
/// `string_width(ctx, offset, length)` is `Font::GetStringWidth(text, offset, length)`, `char_width(ctx, index)`
/// is `Font::GetCharacterWidth(text[index])`, or of 'M' for a negative index.
struct EeWonTextMeasure {
  void *ctx;
  int32_t (*string_width)(void*, int32_t, int32_t);
  int32_t (*char_width)(void*, int32_t);
};

/// The C++ `GUIStringData`'s members as one block (`mText`, `mLength`, `mCapacity`, in that order).
struct EeWonGuiStrBuf {
  /// `wchar_t* mText`: units of `wchar_size` bytes, NULL before the first reservation.
  void *text;
  uint16_t length;
  uint16_t capacity;
};

/// A lobby text, the C++ `GUIStringData`: a C++ `RefCount` without a vtable (NULL: `RefCount::Release` gives the
/// last reference's text to [`ee_won_gstr_free`]), its reference count (atomic; a new text has none, the first
/// `SmartPtr` adds one) and its block.
struct EeWonGstr {
  const void *vtable;
  int32_t refs;
  EeWonGuiStrBuf buf;
};

/// One raw image's pixels: `kind` 0 (1-bit), 1 (8-bit) or 2 (32-bit), its size and its row pitch in bytes.
struct EeWonRawPixels {
  int32_t kind;
  uint8_t *data;
  int32_t width;
  int32_t height;
  int32_t pitch;
};

/// The C++ host: `(shell, op, a, b, c, d) -> result`, `shell` the C++ `WONShell*` the kind belongs to.
using EeWonShellHostFn = ptrdiff_t(*)(void *shell,
                                      EeWonShellHostOp op,
                                      ptrdiff_t a,
                                      ptrdiff_t b,
                                      ptrdiff_t c,
                                      ptrdiff_t d);

/// An input event's fields: the C++ `InputEvent`'s own record (`mEv`; `KeyEvent`, `MouseEvent` and `SizeEvent` fill
/// theirs, the other fields 0).
struct EeWonWinEvent {
  /// the `WindowEventType`
  int32_t kind;
  int32_t x;
  int32_t y;
  int32_t key_mod;
  /// a mouse event's button or wheel amount
  int32_t button;
  /// a key event's key
  int32_t key;
  /// a size event's
  int32_t width;
  int32_t height;
};

/// A window event's record (the C++ `WindowEventBase::mRec`, R6 WON GUI round 38): the input record first (its kind
/// the event's type; the rest an input event's), the window the event is for, and an input event's handler (the
/// `EeWonWinCall` its original class's `Deliver` ran on the window; 0 for any other event, whose `Deliver` is C++).
struct EeWonWmEventRec {
  EeWonWinEvent ev;
  ptrdiff_t window;
  uint32_t handler;
};

/// A component event's record (the C++ `ComponentEvent::mEv`, R6 WON GUI round 39): the original's
/// ComponentEvent members and its GUI subclasses' (ListItemClickedEvent, ComboSelChangedEvent, TreeItemOpenedEvent,
/// TextLinkActivatedEvent: one class since then), read and set in place by Rust in the game. `comp` is the
/// component (held: the original's `mComponentRef` beside the same `mComponent`), `item` the clicked or selected
/// list item, the opened tree row or the activated link (held); `flag` a click's double click or a combo
/// selection's active selection.
struct EeWonCompEventRec {
  ptrdiff_t comp;
  int32_t kind;
  uint8_t broadcast;
  uint8_t flag;
  int32_t button;
  int32_t x;
  int32_t y;
  ptrdiff_t item;
};

#endif  // EE_RUST_WON_GUI_RECORDS_H
